import {assertDisposableFixtureHome} from '../../scripts/quality-gate/go-parity/fixture-guard'
const input=await Bun.stdin.json()
assertDisposableFixtureHome(input.home,'Agent isolated transcript Source')
if(process.env.CC_HAHA_AGENT_TRANSCRIPT_FIXTURE!=='1')throw new Error('Unowned Agent transcript fixture')
await import('../../preload')
const state=await import('../../src/bootstrap/state')
const cwd=await import('../../src/utils/cwd')
const storage=await import('../../src/utils/sessionStorage')
state.setOriginalCwd(input.parentCwd)
state.setProjectRoot(input.parentCwd)
state.setCwdState(input.parentCwd)
state.switchSession(input.sid,null)
const before=storage.getAgentTranscriptPath(input.agentId)
const inside=await cwd.runWithCwdOverride(input.worktree,async()=>({cwd:cwd.getCwd(),original:state.getOriginalCwd(),project:state.getProjectRoot(),path:storage.getAgentTranscriptPath(input.agentId),sid:state.getSessionId()}))
process.stdout.write(JSON.stringify({before,inside,after:storage.getAgentTranscriptPath(input.agentId)})+'\n')
